/*
 * A071037  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 158".
 * https://oeis.org/A071037
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 9999, u16 n <= 9999, u32 n <= 9999, u64 n <= 9999,
 *            u128 n <= 9999, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes a(n) for OEIS A071037: the nth term in the flat triangle
   produced by one‑dimensional cellular automaton Rule 158.  The triangle
   has rows of length 2n + 1, and this routine generates rows incrementally
   until the required row is reached, then returns the element at the
   appropriate offset. */
#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* Find the row number R such that R^2 <= n < (R+1)^2. */
    idx_t R = 0;
    for (;;) {
        idx_t next = R + 1;
        if ((__uint128_t)next * next > n)
            break;
        ++R;
    }

    /* Base row: single cell 1. */
    uint8_t *prev = (uint8_t *)malloc(1);
    if (!prev)                          /* allocation failure guard */
        return (seq_t)0;
    prev[0] = 1;

    /* Generate rows 1 … R. */
    for (idx_t r = 1; r <= R; ++r) {
        idx_t prev_len = (r - 1) * 2 + 1;   /* length of previous row */
        idx_t curr_len = r * 2 + 1;         /* length of current row  */
        uint8_t *curr = (uint8_t *)malloc(curr_len);
        if (!curr) {                       /* allocation failure guard */
            free(prev);
            return (seq_t)0;
        }

        for (idx_t k = 0; k < curr_len; ++k) {
            uint8_t left  = (k >= 2) ? prev[k - 2] : 0;
            uint8_t mid   = (k >= 1 && k - 1 < prev_len) ? prev[k - 1] : 0;
            uint8_t right = (k < prev_len) ? prev[k] : 0;
            uint8_t pattern = (left << 2) | (mid << 1) | right;
            /* Rule 158: binary 10011110 = 0b10011110. */
            curr[k] = (uint8_t)((158u >> pattern) & 1u);
        }

        free(prev);
        prev = curr;
    }

    /* Retrieve the desired element. */
    idx_t offset = n - R * R;          /* 0 <= offset < 2R+1 */
    uint8_t result = prev[offset];
    free(prev);
    return (seq_t)result;
}
